test("RF-004: transferir registra un egreso en origen y un ingreso en destino", () => {
  const antes = conIngreso();
  const despues = transferir(antes, { articulo: "A1", origen: "LPZ", destino: "SCZ", cantidad: 4 });
  assert.equal(antes.length, 1);
  assert.ok(Object.isFrozen(despues));
  assert.deepEqual(despues.slice(1), [
    { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 4 },
    { tipo: "ingreso", articulo: "A1", almacen: "SCZ", cantidad: 4 },
  ]);
  assert.equal(stock(despues, "A1", "LPZ"), 6);
  assert.equal(stock(despues, "A1", "SCZ"), 4);
});

test("RF-004 / RF-002: transferir más del stock de origen se rechaza sin registrar nada", () => {
  const antes = conIngreso();
  assert.throws(() => transferir(antes, { articulo: "A1", origen: "LPZ", destino: "SCZ", cantidad: 11 }), /Stock insuficiente/);
  assert.throws(() => transferir(antes, { articulo: "A1", origen: "SCZ", destino: "LPZ", cantidad: 1 }), /Stock insuficiente/);
  assert.equal(antes.length, 1);
});

test("RF-004: transferencias inválidas se rechazan", () => {
  const movs = conIngreso();
  assert.throws(() => transferir(movs, { articulo: "A1", origen: "LPZ", destino: "LPZ", cantidad: 1 }), /distinto/);
  assert.throws(() => transferir(movs, { articulo: "A1", origen: "LPZ", destino: "", cantidad: 1 }));
  assert.throws(() => transferir(movs, { articulo: "A1", origen: "", destino: "SCZ", cantidad: 1 }));
  assert.throws(() => transferir(movs, { articulo: "A1", origen: "LPZ", destino: "SCZ", cantidad: 0 }), RangeError);
  assert.throws(() => transferir(movs, { articulo: "A1", origen: "LPZ", destino: "SCZ", cantidad: 1.5 }), RangeError);
});
